mapper.update:
UPDATE CHATBOT_CONVERSATION
   SET title = #{title}
 WHERE conversation_id = #{conversationId}

UPDATE CHATBOT_CONVERSATION
   SET last_active = NOW()
 WHERE conversation_id = #{conversationId}

UPDATE CHATBOT_CONVERSATION
   SET is_deleted = 1
 WHERE conversation_id = #{conversationId}

UPDATE CHATBOT_CONVERSATION
   SET sort_order = #{sortOrder}
 WHERE conversation_id = #{conversationId}

mapper.select:
SELECT COUNT(*)
FROM CHATBOT_CONVERSATION
WHERE is_deleted = 0

      AND user_idx = #{userIdx}
      AND anon_session_id = #{anonSessionId}

SELECT c.conversation_id, c.user_idx, c.anon_session_id, c.title, c.ip_address, c.created_at, c.last_active, c.is_deleted, (SELECT COUNT(*) FROM CHATBOT_MESSAGE m WHERE m.conversation_id = c.conversation_id) AS message_count FROM CHATBOT_CONVERSATION c
LEFT JOIN USERS u ON c.user_idx = u.user_idx WHERE c.title LIKE CONCAT('%', #{keyword}, '%') OR c.ip_address LIKE CONCAT('%', #{keyword}, '%') OR c.anon_session_id LIKE CONCAT('%', #{keyword}, '%') OR u.user_id LIKE CONCAT('%', #{keyword}, '%')
ORDER BY c.last_active DESC LIMIT #{limit} OFFSET #{offset}
